/**
 * Body of the `409` answers that mean "not this run".
 *
 * Distinct from [`GenerationRunningError`] for the reason 781-B's
 * `NothingToReactError` is: that one says "not now", this one says "not this
 * run". `code` is what the client discriminates on.
 */
export type NotRetryableError = {
  /**
   * The child run the client asked to retry.
   *
   * @format uuid
   */
  chat_id: string;
  /**
   * Always `not_retryable`.
   */
  code: string;
  message?: null | undefined;
  state: NotRetryableState;
};

/**
 * Why a run cannot be retried. A closed vocabulary, because the client
 * switches on it to choose between hiding the control, linking to the run
 * that already replaced this one, and showing a reason.
 */
export type NotRetryableState =
  | "retry_in_flight"
  | "completed"
  | "working"
  | "not_a_task_run"
  | "brief_unavailable"
  | "concurrency_cap"
  | "launch_refused";

/**
 * Body of the `409` `/react` answers when there is nothing to react to.
 *
 * Distinct from [`GenerationRunningError`] because the two are different
 * decisions: that one says "not now", this one says "not this row, ever".
 * `code` is what the client discriminates on; `reason` is what it uses to
 * choose between suppressing the affordance and offering a re-anchor.
 */
export type NothingToReactError = {
  /**
   * @format uuid
   */
  chat_id: string;
  /**
   * Always `nothing_to_react`.
   */
  code: string;
  /**
   * One of `not_a_task_result`, `not_delivered`, `already_reacted`,
   * `tip_moved`.
   */
  reason: string;
  /**
   * @format uuid
   */
  task_result_message_id: string;
};

