export type RecentChat = {
  /**
   * Start time of the chat's generation, present only while it is running
   * with a fresh heartbeat
   *
   * @format date-time
   */
  active_generation_started_at?: string;
  /**
   * When this chat was archived by the user.
   *
   * @format date-time
   */
  archived_at?: string;
  /**
   * The assistant ID if this chat is based on an assistant
   */
  assistant_id?: string;
  /**
   * The name of the assistant if this chat is based on an assistant
   */
  assistant_name?: string;
  /**
   * Whether the current user can edit this chat (e.g., edit messages)
   *
   * NOTE: Currently this is true only for the chat owner. In the future,
   * this may include collaborators/roles/policy-based permissions.
   */
  can_edit: boolean;
  /**
   * Terminal outcome of a delegated run: `completed` when the run landed a
   * clean assistant answer, `failed` when it did not (unanswered, errored,
   * or killed). Absent while the run is live and for chats that are not
   * delegated runs. Derived from the chat's own content, so it stays
   * accurate long after the live generation status expires — a fresh
   * client sees the terminal state without ever having observed the run.
   *
   * @example completed
   */
  delegated_run_outcome?: string;
  /**
   * Whether any async delegated run spawned from this chat is still owed
   * back to it — unfinished, or holding an undelivered result. Clients use
   * this to keep the generation-status poll alive while a detached run is
   * outstanding. Always present.
   */
  delegated_runs_in_flight: boolean;
  /**
   * MCP servers the user switched off for this chat; their tools are not
   * offered to the model.
   */
  disabled_mcp_server_ids: string[];
  /**
   * `server/tool` patterns of MCP tools the user switched off for this
   * chat; matching tools are not offered to the model.
   */
  disabled_mcp_tools: string[];
  /**
   * Files uploaded to this chat
   */
  file_uploads: FileReference[];
  id: string;
  /**
   * Whether this chat is pinned by its owner.
   */
  is_pinned: boolean;
  /**
   * The chat provider ID used for the most recent message
   */
  last_chat_provider_id?: string;
  /**
   * Time of the last message in the chat.
   *
   * @format date-time
   */
  last_message_at: string;
  last_model?: ChatModel;
  /**
   * The facets selected for the most recent message
   */
  last_selected_facets?: string[];
  /**
   * Whether the model may be offered MCP write tools and client actions
   * in this chat. Off, only tools the server marks read-only are offered.
   */
  mcp_write_tools_enabled: boolean;
  /**
   * The assistant bound to the origin chat at spawn time, if any.
   */
  origin_assistant_id?: string;
  /**
   * The origin chat this chat was spawned from, if any. May reference a
   * deleted chat.
   */
  origin_chat_id?: string;
  /**
   * Resolved display title of the origin chat; absent when the origin no
   * longer exists.
   */
  origin_chat_title?: string;
  /**
   * Present while the chat's generation is stopped on an MCP tool approval
   * awaiting the user's decision
   *
   * @format date-time
   */
  pending_tool_approval_at?: string;
  /**
   * Provenance kind when the chat was spawned from another chat (e.g.
   * `delegation` for a delegated run). Clients derive "is delegated run"
   * from this value.
   */
  provenance_kind?: string;
  /**
   * How a delegated run was dispatched. Present only for delegation
   * provenance, and only for a detached run: `background`, whose result
   * never flows back to the origin turn, or `async`, whose result is
   * delivered into the origin chat later as its own row. An awaited run
   * omits it, since its answer already returned inline.
   *
   * @example background
   */
  provenance_run_mode?: string;
  /**
   * The failed delegated run this one was started to replace. Present only
   * on a retry child. Clients use it to swap a failed run's retry button for
   * a link to the run that replaced it, durably - it survives a reload,
   * where component state would not.
   */
  retry_of?: string;
  /**
   * Title of the chat as generated by summary automation.
   */
  title_by_summary?: string | null | undefined;
  /**
   * Title of the chat as explicitly provided by the user.
   */
  title_by_user_provided?: string | null | undefined;
  /**
   * Resolved chat title where user-provided title takes precedence over summary title.
   */
  title_resolved: string;
};

